<script>
(function(){const form=document.getElementById('quiz-form'),total={{ $ordered->count() }},deadline=Date.parse(@json($deadline->toIso8601String())),offset=Date.parse(@json(now('Asia/Dhaka')->toIso8601String()))-Date.now();let sent=false;function count(){const n=form.querySelectorAll('input[type=radio]:checked').length;document.getElementById('answered').textContent=n;document.getElementById('bar').style.width=(total?n*100/total:0)+'%'}form.addEventListener('change',count);function submit(){if(sent)return;sent=true;form.submit()}document.getElementById('submit-btn').addEventListener('click',function(){if(confirm('আপনি কি পরীক্ষা জমা দিতে চান?'))submit()});function tick(){if(sent)return;let sec=Math.max(0,Math.ceil((deadline-Date.now()-offset)/1000));document.getElementById('timer').textContent=sec?String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0'):'সময় শেষ';if(sec===0)submit()}tick();setInterval(tick,1000);count()})();
</script>
